-- Renta variable (certificados de participación y acciones): rendimiento estimado y notas de valuación según CARE.
-- La app simula estos títulos como si pagaran el rendimiento estimado sobre un precio base de 100.
update instrumentos set rendimiento_estimado=5.2, vencimiento_manual=coalesce(vencimiento_manual, date '2031-12-31'), frecuencia=1, notas='Forestal Bosques del Uruguay (I). CP por USD 50 MM emitidos en ago-2011. Distribuciones irregulares (cuando hay fondos netos, ventas de activos o liquidación). TIR desde la emisión: CARE 5,2% (escenario base), rango 4,0% a 5,2%; liquidación prevista 2031. Ojo: el rendimiento es para quien entró a la par; si el precio de mercado está por encima de 100, comprando hoy se gana menos. Fuente: CARE, abr-2026.' where isin='UYFF00010US7' and cupon_manual is null and cupon is null;
